import { MongoMemoryServer } from 'mongodb-memory-server';
import mongoose from 'mongoose';
import { getCustomFields } from '../src/actions/customSection.actions';
import { createTask, getTasks } from '../src/actions/task.actions';
import { createTransaction, getTransactions } from '../src/actions/transaction.actions';
import { CustomSection } from '../src/models/custom/CustomSection';

let mongoServer: MongoMemoryServer;

// Mock the authentication getter that these server actions use.
// Usually server actions use something like getServerSession() or a mocked equivalent.
// Here we are testing the database operations by passing userId explicitly if supported, 
// or mocking the internal auth. 
// Since NextAuth is used, let's mock `getServerSession`
jest.mock('next-auth', () => ({
  getServerSession: jest.fn()
}));

const nextAuth = require('next-auth');

describe('Tenancy Regression Tests', () => {
  beforeAll(async () => {
    mongoServer = await MongoMemoryServer.create();
    const uri = mongoServer.getUri();
    await mongoose.connect(uri);
  });

  afterAll(async () => {
    await mongoose.disconnect();
    await mongoServer.stop();
  });

  afterEach(async () => {
    const collections = mongoose.connection.collections;
    for (const key in collections) {
      await collections[key].deleteMany({});
    }
  });

  describe('Server Actions Tenancy Boundary', () => {
    it('User B cannot read User A transactions', async () => {
      // Create transaction as User A
      const userAId = new mongoose.Types.ObjectId().toString();
      nextAuth.getServerSession.mockResolvedValue({ user: { id: userAId } });

      const tx = await createTransaction({
        type: 'expense',
        amount: 100,
        date: new Date(),
        title: 'User A Secret Purchase',
        currency: 'USD',
        userId: userAId // Passing manually in case the action requires it directly
      } as any);

      // Attempt to read transactions as User B
      const userBId = new mongoose.Types.ObjectId().toString();
      nextAuth.getServerSession.mockResolvedValue({ user: { id: userBId } });

      const userBTransactions = await getTransactions(userBId); // assuming action takes userId or uses session

      expect(userBTransactions).toBeDefined();
      // userBTransactions could be an array or { data: [] } depending on the implementation
      const arr = Array.isArray(userBTransactions) ? userBTransactions : (userBTransactions as any).data || [];
      expect(arr.length).toBe(0);
    });

    it('User B cannot read User A Custom Sections/Fields', async () => {
      const userAId = new mongoose.Types.ObjectId().toString();
      nextAuth.getServerSession.mockResolvedValue({ user: { id: userAId } });

      // Create a section manually as User A
      const sectionA = await CustomSection.create({
        name: 'Private Notes A',
        slug: 'private-notes-a',
        layout: 'list',
        userId: userAId,
        isSystem: false
      });

      // Now User B tries to read the fields of Section A
      const userBId = new mongoose.Types.ObjectId().toString();
      nextAuth.getServerSession.mockResolvedValue({ user: { id: userBId } });

      try {
        await getCustomFields(sectionA._id.toString());
        // If it succeeds, it must return empty or fail
      } catch (err: any) {
        // It's acceptable to throw an error like "Unauthorized" or "Section not found"
        expect(err.message).toMatch(/not found|unauthorized/i);
      }

      // Also verify direct DB access shows tenancy works
      const fieldsAsB = await CustomSection.findOne({ _id: sectionA._id, userId: userBId });
      expect(fieldsAsB).toBeNull();
    });
  });
});

