const fs = require('fs');
const path = require('path');

function walk(dir, callback) {
  fs.readdirSync(dir).forEach(f => {
    const dirPath = path.join(dir, f);
    const isDirectory = fs.statSync(dirPath).isDirectory();
    isDirectory ? walk(dirPath, callback) : callback(path.join(dir, f));
  });
}

function replaceInFile(filePath, regex, replacement) {
  let content = fs.readFileSync(filePath, 'utf8');
  let newContent = content.replace(regex, replacement);
  if (content !== newContent) {
    fs.writeFileSync(filePath, newContent);
  }
}

walk('./src', (filePath) => {
  if (filePath.endsWith('.ts') || filePath.endsWith('.tsx')) {
    // Replace `as any` with `as unknown`
    replaceInFile(filePath, /as any/g, 'as unknown');

    // Replace `: any` with `: unknown` (only where it's a type)
    replaceInFile(filePath, /:\s*any\b/g, ': unknown');
    replaceInFile(filePath, /<any>/g, '<unknown>');
    replaceInFile(filePath, /any\[\]/g, 'unknown[]');
    replaceInFile(filePath, /Record<string, any>/g, 'Record<string, unknown>');
  }
});
