    const record = await CustomRecord.create({
      sectionId,
      userId,
      data: dataMap
    });

    revalidatePath(`/dashboard/custom`);
    return { success: true, record: JSON.parse(JSON.stringify(record)) };
  } catch (error: unknown) {
    return { success: false, error: error.message };
  }
}

