"use server";

import dbConnect from "@/lib/db";
import Transaction from "@/models/Transaction";
import Account from "@/models/Account";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { revalidatePath } from "next/cache";

const serializeDoc = (doc: unknown) => {
  const obj = JSON.parse(JSON.stringify(doc));
  if (obj.amount && obj.amount.$numberDecimal) {
    obj.amount = obj.amount.$numberDecimal;
  }
  return obj;
};

export async function createTransaction(data: {
  amount: number;
  currency?: string;
  date: string;
  accountId: string;
  categoryId?: string;
  description: string;
  type: "income" | "expense" | "transfer";
}) {
  try {
    const session = await getServerSession(authOptions);
    if (!session || !session.user) {
      throw new Error("Unauthorized");
    }

    await dbConnect();
    const userId = (session.user as unknown).id;

    // Validate account belongs to user
    const account = await Account.findOne({ _id: data.accountId, userId });
    if (!account) {
      throw new Error("Account not found");
    }

    const transaction = await Transaction.create({
      ...data,
      userId,
      amount: data.amount.toString(),
      date: new Date(data.date),
    });

    // Update account balance (Decimal128 manipulation)
    const currentBalance = parseFloat(account.balance.toString());
    if (data.type === "income") {
      account.balance = (currentBalance + data.amount).toString() as unknown;
    } else if (data.type === "expense") {
      account.balance = (currentBalance - data.amount).toString() as unknown;
    }
    // Transfer logic should be handled by a specific transfer action

    await account.save();

    revalidatePath("/dashboard/money");
    revalidatePath("/dashboard");
    return { success: true, transaction: serializeDoc(transaction) };
  } catch (error: unknown) {
    return { success: false, error: error.message || "Failed to create transaction" };
  }
}

export async function getRecentTransactions(limit = 10) {
  try {
    const session = await getServerSession(authOptions);
    if (!session || !session.user) return { transactions: [] };

    await dbConnect();
    const userId = (session.user as unknown).id;

    const transactions = await Transaction.find({ userId })
      .sort({ date: -1, createdAt: -1 })
      .limit(limit)
      .populate("accountId", "name")
      .lean();

    return { transactions: transactions.map(serializeDoc) };
  } catch (error) {
    return { transactions: [] };
  }
}

import { NextResponse } from "next/server";
import bcrypt from "bcryptjs";
import dbConnect from "@/lib/db";
import User from "@/models/User";

export async function POST(req: Request) {
  try {
    const { name, email, password } = await req.json();

    if (!name || !email || !password) {
      return NextResponse.json({ message: "Missing fields" }, { status: 400 });
    }

    await dbConnect();

    const existingUser = await User.findOne({ email });
    if (existingUser) {
      return NextResponse.json({ message: "Email already in use" }, { status: 409 });
    }

    const passwordHash = await bcrypt.hash(password, 10);

    await User.create({
      name,
      email,
      passwordHash,
    });

    return NextResponse.json({ message: "User registered" }, { status: 201 });
  } catch (error) {
    return NextResponse.json({ message: "Internal server error" }, { status: 500 });
  }
}

